/**
 * @description Displays rich tables that support pagination, sorting, filtering, and interactivity.
 * @see {@link https://docs.slack.dev/reference/block-kit/blocks/data-table-block Data table block reference}.
 */
export interface DataTableBlock extends Block {
  /**
   * @description The type of block. For a data table block, `type` is always `data_table`.
   */
  type: 'data_table';
  /**
   * @description An array consisting of table rows.
   */
  rows: (RawTextElement | RawNumberElement | RichTextBlock)[][];
  /**
   * @description A caption for the table; used as the value for the HTML caption element.
   */
  caption: string;
  /**
   * @description Number of rows per page. Min `1`, Max `100`. Defaults to `5` if omitted.
   */
  page_size?: number;
  /**
   * @description The 0-based index of the column that uniquely identifies each row (the row header). This column is treated as the row's primary identifier for screen readers. Defaults to `0` if omitted.
   */
  row_header_column_index?: number;
}

/**
 * @description Visually separates pieces of info inside of a message. A content divider, like an `<hr>`, to split up
 * different blocks inside of a message. The divider block is nice and neat, requiring only a `type`.
 * @see {@link https://docs.slack.dev/reference/block-kit/blocks/divider-block Divider block reference}.
 */
export interface DividerBlock extends Block {
  /**
   * @description The type of block. For a divider block, `type` is always `divider`.
   */
  type: 'divider';
}

/**
 * @description Displays a {@link https://docs.slack.dev/messaging/working-with-files#remote remote file}. You can't add this block to
 * app surfaces directly, but it will show up when {@link https://docs.slack.dev/messaging/retrieving-messages retrieving messages}
 * that contain remote files. If you want to add remote files to messages,
 * {@link https://docs.slack.dev/messaging/working-with-files#remote follow our guide}.
 * @see {@link https://docs.slack.dev/reference/block-kit/blocks/file-block File block reference}.
 */
export interface FileBlock extends Block {
  /**
   * @description The type of block. For a file block, `type` is always `file`.
   */
  type: 'file';
  /**
   * @description At the moment, source will always be `remote` for a remote file.
   */
  source: string; // TODO: breaking change: set this to the string literal 'remote'
  /**
   * @description The external unique ID for this file.
   */
  external_id: string;
}

/**
 * @description Displays a larger-sized text block. A `header` is a plain-text block that displays in a larger, bold
 * font. Use it to delineate between different groups of content in your app's surfaces.
 * @see {@link https://docs.slack.dev/reference/block-kit/blocks/header-block Header block reference}.
 */
export interface HeaderBlock extends Block {
  /**
   * @description The type of block. For a header block, `type` is always `header`.
   */
  type: 'header';
  /**
   * @description The text for the block, in the form of a {@link PlainTextElement}.
   * Maximum length for the text in this field is 150 characters.
   */
  text: PlainTextElement;
}

/**
 * @description Displays an image. A simple image block, designed to make those cat photos really pop.
 * @see {@link https://docs.slack.dev/reference/block-kit/blocks/image-block Image block reference}.
 */
export type ImageBlock = {
  /**
   * @description The type of block. For an image block, `type` is always `image`.
   */
  type: 'image';
  /**
   * @description A plain-text summary of the image. This should not contain any markup.
   * Maximum length for this field is 2000 characters.
   */
  alt_text: string;
  /**
   * @description An optional title for the image in the form of a {@link PlainTextElement} object.
   * Maximum length for the text in this field is 2000 characters.
   */
  title?: PlainTextElement;
} & Block &
  (UrlImageObject | SlackFileImageObject);

/**
 * A helper union type of all Block Elements that can be used in an {@link InputBlock}.
 * @see {@link https://docs.slack.dev/reference/block-kit/blocks/input-block Input block reference}.
 */
export type InputBlockElement =
  | Checkboxes
  | Datepicker
  | DateTimepicker
  | EmailInput
  | FileInput
  | MultiSelect
  | NumberInput
  | PlainTextInput
  | RadioButtons
  | RichTextInput
  | Select
  | Timepicker
  | URLInput;

/**
 * @description Collects information from users via block elements.
 * @see {@link https://docs.slack.dev/reference/block-kit/blocks/input-block Input block reference}.
 * @see {@link https://docs.slack.dev/surfaces/modals#gathering_input Collecting input in modals guide}.
 * @see {@link https://docs.slack.dev/surfaces/app-home Collecting input in Home tabs guide}.
 */
export interface InputBlock extends Block {
  /**
   * @description The type of block. For an input block, `type` is always `input`.
   */
  type: 'input';
  /**
   * @description A label that appears above an input element in the form of a {@link PlainTextElement} object.
   * Maximum length for the text in this field is 2000 characters.
   */
  label: PlainTextElement;
  /**
   * @description An optional hint that appears below an input element in a lighter grey. It must be a
   * {@link PlainTextElement object}. Maximum length for the `text` in this field is 2000 characters.
   */
  hint?: PlainTextElement;
  /**
   * @description A boolean that indicates whether the input element may be empty when a user submits the modal.
   * Defaults to `false`.
   */
  optional?: boolean;
  /**
   * @description A block element.
   */
  element: InputBlockElement;
  /**
   * @description A boolean that indicates whether or not the use of elements in this block should dispatch a
   * {@link https://docs.slack.dev/reference/interaction-payloads/block_actions-payload block_actions payload}. Defaults to `false`.
   */
  dispatch_action?: boolean;
}

/**
 * @description This block can be used with AI apps when you expect a markdown response from an LLM that can get lost in
 * translation rendering in Slack. Providing it in a markdown block leaves the translating to Slack to ensure your message
 * appears as intended. Note that passing a single block may result in multiple blocks after translation.
 * @see {@link https://api.slack.com/reference/block-kit/blocks#markdown Markdown block reference}.
 */
export interface MarkdownBlock extends Block {
  /**
   * @description The type of block. For a markdown block, `type` is always `markdown`.
   */
  type: 'markdown';
  /**
   * @description The standard markdown-formatted text. Limit 12,000 characters max.
   */
  text: string;
}

/**
 * A helper union type of all Block Elements that can be used in a {@link RichTextBlock}.
 * @see {@link https://docs.slack.dev/reference/block-kit/blocks/rich-text-block Rich text block reference}.
 */
export type RichTextBlockElement = RichTextSection | RichTextList | RichTextQuote | RichTextPreformatted;

/**
 * @description Displays formatted, structured representation of text. It is also the output of the Slack client's
 * WYSIWYG message composer, so all messages sent by end-users will have this format. Use this block to include
 * user-defined formatted text in your Block Kit payload. While it is possible to format text with `mrkdwn`,
 * `rich_text` is strongly preferred and allows greater flexibility.
 * You might encounter a `rich_text` block in a message payload, as a built-in type in workflow apps, or as output of
 * the {@link RichTextInput}.
 * @see {@link https://docs.slack.dev/reference/block-kit/blocks/rich-text-block Rich text block reference}.
 */
export interface RichTextBlock extends Block {
  /**
   * @description The type of block. For a rich text block, `type` is always `rich_text`.
   */
  type: 'rich_text';
  elements: RichTextBlockElement[];
}

/**
 * A helper union type of all Block Elements that can be used as an accessory in a {@link SectionBlock}.
 * @see {@link https://docs.slack.dev/reference/block-kit/blocks/section-block Section block reference}.
 */
export type SectionBlockAccessory =
  | Button
  | Checkboxes
  | Datepicker
  | ImageElement
  | MultiSelect
  | Overflow
  | RadioButtons
  | Select
  | Timepicker
  | WorkflowButton;

// TODO: breaking change: use a discriminative union to represent section block using `text` or `fields` but
// not both or neither.
/**
 * @description Displays text, possibly alongside block elements. A section can be used as a simple text block, in
 * combination with text fields, or side-by-side with certain
 * {@link https://docs.slack.dev/reference/block-kit/block-elements block elements}.
 * @see {@link https://docs.slack.dev/reference/block-kit/blocks/section-block Section block reference}.
 */
export interface SectionBlock extends Block {
  /**
   * @description The type of block. For a section block, `type` is always `section`.
   */
  type: 'section';
  /**
   * @description The text for the block, in the form of a {@link TextObject}. Minimum length for the `text` in this
   * field is 1 and maximum length is 3000 characters. This field is not required if a valid array of `fields` objects
   * is provided instead.
   */
  text?: TextObject;
  /**
   * @description Required if no `text` is provided. An array of text objects. Any text objects included with `fields`
   * will be rendered in a compact format that allows for 2 columns of side-by-side text. Maximum number of items is 10.
   * Maximum length for the text in each item is 2000 characters.
   * {@link https://app.slack.com/block-kit-builder/#%7B%22blocks%22:%5B%7B%22type%22:%22section%22,%22text%22:%7B%22text%22:%22A%20message%20*with%20some%20bold%20text*%20and%20_some%20italicized%20text_.%22,%22type%22:%22mrkdwn%22%7D,%22fields%22:%5B%7B%22type%22:%22mrkdwn%22,%22text%22:%22*Priority*%22%7D,%7B%22type%22:%22mrkdwn%22,%22text%22:%22*Type*%22%7D,%7B%22type%22:%22plain_text%22,%22text%22:%22High%22%7D,%7B%22type%22:%22plain_text%22,%22text%22:%22String%22%7D%5D%7D%5D%7D Click here for an example}.
   */
  fields?: TextObject[]; // either this or text must be defined, also min 1 item
  /**
   * @description One of the compatible element objects.
   */
  accessory?: SectionBlockAccessory;
  /**
   * Whether or not this section block's text should always expand when rendered. If false or not provided, it may be rendered with a 'see more' option to expand and show the full text. For AI Assistant apps, this allows the app to post long messages without users needing to click 'see more' to expand the message.
   */
  expand?: boolean;
}

/**
 * @description Displays structured information in a table.
 * @see {@link https://docs.slack.dev/reference/block-kit/blocks/table-block Table block reference}.
 */
export interface TableBlock extends Block {
  /**
   * @description The type of block. For a table block, `type` is always `table`.
   */
  type: 'table';
  /**
   * @description An array consisting of table rows. Maximum 100 rows. Each row object is an array with a max of 20 table cells. Table cells can have a type of rich_text, raw_text, or raw_number.
   */
  rows: (RichTextBlock | RawTextElement | RawNumberElement)[][];
  /**
   * @description An array describing column behavior. If there are fewer items in the column_settings array than there are columns in the table, then the items in the the column_settings array will describe the same number of columns in the table as there are in the array itself. Any additional columns will have the default behavior. Maximum 20 items.
   */
  column_settings?: TableBlockColumnSettings[];
}

/**
 * Schema for column_settings of the table block.
 * @see {@link https://docs.slack.dev/reference/block-kit/blocks/table-block/#schema-for-column_settings}.
 */
interface TableBlockColumnSettings {
  /**
   * @description The alignment for items in this column. Can be left, center, or right. Defaults to left if not defined.
   */
  align?: 'left' | 'center' | 'right';
  /**
   * @description Whether the contents of this column should be wrapped or not. Defaults to false if not defined.
   */
  is_wrapped?: boolean;
}

/**
 * @description A discrete task or tool call.
 * @see https://docs.slack.dev/reference/block-kit/blocks/task-card-block/
 */
export interface TaskCardBlock extends Block {
  /**
   * @description The type of block. For this block, type will always be `task_card`.
   */
  type: 'task_card';

  /**
   * @description ID for the task.
   */
  task_id: string;

  /**
   * @description Title of the task in plain text.
   */
  title: string;

  /**
   * @description Details of the task in the form of a single "rich_text" entity.
   */
  details?: RichTextBlock;

  /**
   * @description Output of the task in the form of a single "rich_text" entity.
   */
  output?: RichTextBlock;

  /**
   * @description Array of URL source elements used to generate a response.
   */
  sources?: URLSourceElement[];

  /**
   * @description The state of a task. Can be "pending", "in_progress", "complete", or "error".
   */
  status: 'pending' | 'in_progress' | 'complete' | 'error';
}

/**
 * @description A collection of related tasks.
 * @see https://docs.slack.dev/reference/block-kit/blocks/plan-block/
 */
export interface PlanBlock extends Block {
  /**
   * @description The type of block. In this case `type` is always `plan`.
   */
  type: 'plan';

  /**
   * @description Title of the plan in plain text.
   */
  title: string;

  /**
   * @description A sequence of task card blocks. Each task represents a single action within the plan.
   */
  tasks?: (TaskCardBlock | Record<string, unknown>)[];
}

/**
 * @description Displays an embedded video player. A video block is designed to embed videos in all app surfaces (e.g.
 * link unfurls, messages, modals, App Home) — anywhere you can put blocks! To use the video block within your app, you
 * must have the {@link https://docs.slack.dev/reference/scopes/links.embed.write `links.embed:write` scope}.
 * @see {@link https://docs.slack.dev/reference/block-kit/blocks/video-block Video block reference}.
 */
export interface VideoBlock extends Block {
  /**
   * @description The type of block. For a video block, `type` is always `video`.
   */
  type: 'video';
  /**
   * @description The URL to be embedded. Must match any existing
   * {@link https://docs.slack.dev/messaging/unfurling-links-in-messages unfurl domains} within the app
   * and point to a HTTPS URL.
   */
  video_url: string;
  /**
   * @description The thumbnail image URL.
   */
  thumbnail_url: string;
  /**
   * @description A tooltip for the video. Required for accessibility.
   */
  alt_text: string;
  /**
   * @description Video title as a {@link PlainTextElement} object. `text` within must be less than 200 characters.
   */
  title: PlainTextElement;
  /**
   * @description Hyperlink for the title text. Must correspond to the non-embeddable URL for the video.
   * Must go to an HTTPS URL.
   */
  title_url?: string;
  /**
   * @description Author name to be displayed. Must be less than 50 characters.
   */
  author_name?: string;
  /**
   * @description The originating application or domain of the video, e.g. YouTube.
   */
  provider_name?: string;
  /**
   * @description Icon for the video provider, e.g. YouTube icon.
   */
  provider_icon_url?: string;
  /**
   * @description Description for video using a {@link PlainTextElement} object.
   */
  description?: PlainTextElement;
}

// This file contains objects documented here: https://docs.slack.dev/reference/block-kit/composition-objects

/**
 * Re-usable labels for common color schemes present in Slack. `danger` displays with a red background (red text on
 * mobile), while `primary` displays with a green background (green text on mobile).
 */
export type ColorScheme = 'primary' | 'danger';

/** The conversation type as available within the Slack UI. */
export type ConversationType = 'im' | 'mpim' | 'private' | 'public';

// TODO: breaking change: remove `Confirm` and move properties to `ConfirmationDialog` below on next major release.
/**
 * @deprecated {@link Confirm} aliased to {@link ConfirmationDialog} in order to make the construct clearer
 * and line up terminology with docs.slack.dev.
 * @description Defines a dialog that adds a confirmation step to interactive elements.
 * @see {@link https://docs.slack.dev/reference/block-kit/composition-objects/confirmation-dialog-object Confirmation dialog object reference}.
 */
export interface Confirm {
  /**
   * @description A {@link PlainTextElement} text object that defines the dialog's title.
   * Maximum length for this field is 100 characters.
   */
  title?: PlainTextElement; // TODO: breaking change, title is required according to https://docs.slack.dev/reference/block-kit/composition-objects/confirmation-dialog-object
  /**
   * @description A {@link PlainTextElement} text object that defines the explanatory text that appears in the confirm
   * dialog. Maximum length for the `text` in this field is 300 characters.
   */
  text: PlainTextElement | MrkdwnElement; // TODO: breaking change: this should not be a mrkdwnelement
  /**
   * @description A {@link PlainTextElement} text object to define the text of the button that confirms the action.
   * Maximum length for the `text` in this field is 30 characters.
   */
  confirm?: PlainTextElement; // TODO: breaking change, confirm is required according to https://docs.slack.dev/reference/block-kit/composition-objects/confirmation-dialog-object
  /**
   * @description A {@link PlainTextElement} text object to define the text of the button that cancels the action.
   * Maximum length for the `text` in this field is 30 characters.
   */
  deny?: PlainTextElement; // TODO: breaking change, deny is required according to https://docs.slack.dev/reference/block-kit/composition-objects/confirmation-dialog-object
  /**
   * @description Defines the color scheme applied to the `confirm` button. A value of `danger` will display the button
   * with a red background on desktop, or red text on mobile. A value of `primary` will display the button with a green
   * background on desktop, or blue text on mobile. If this field is not provided, the default value will be `primary`.
   */
  style?: ColorScheme;
}

/**
 * @description Defines a dialog that adds a confirmation step to interactive elements.
 * @see {@link https://docs.slack.dev/reference/block-kit/composition-objects/confirmation-dialog-object Confirmation dialog object reference}.
 */
export interface ConfirmationDialog extends Confirm {}

/**
 * @description Defines when a {@link PlainTextElement} will return a {@link https://docs.slack.dev/reference/interaction-payloads/block_actions-payload `block_actions` interaction payload}.
 * @see {@link https://docs.slack.dev/reference/interaction-payloads/block_actions-payload `block_actions` interaction payload}.
 */
export interface DispatchActionConfig {
  /**
   * @description An array of interaction types that you would like to receive a
   * {@link https://docs.slack.dev/reference/interaction-payloads/block_actions-payload `block_actions` payload} for. Should be
   * one or both of:
   *   `on_enter_pressed` — payload is dispatched when user presses the enter key while the input is in focus. Hint
   *   text will appear underneath the input explaining to the user to press enter to submit.
   *   `on_character_entered` — payload is dispatched when a character is entered (or removed) in the input.
   */
  trigger_actions_on?: ('on_enter_pressed' | 'on_character_entered')[];
}

interface OptionDescriptor {
  /**
   * @description A unique string value that will be passed to your app when this option is chosen.
   * Maximum length for this field is 75 characters.
   */
  value?: string; // TODO: breaking change - value is required according to https://docs.slack.dev/reference/block-kit/composition-objects/option-object
  /**
   * @description Only available in overflow menus! A URL to load in the user's browser when the option is clicked.
   * Maximum length for this field is 3000 characters.
   */
  url?: string;
  /**
   * @description A {@link PlainTextElement} that defines a line of descriptive text shown below the `text` field.
   * Maximum length for the `text` within this field is 75 characters.
   */
  description?: PlainTextElement;
}

export interface MrkdwnOption extends OptionDescriptor {
  /**
   * @description A {@link MrkdwnElement} that defines the text shown in the option on the menu. To be used with
   * radio buttons and checkboxes. Maximum length for the `text` in this field is 75 characters.
   */
  text: MrkdwnElement;
}

export interface PlainTextOption extends OptionDescriptor {
  /**
   * @description A {@link PlainTextElement} that defines the text shown in the option on the menu. To be used with
   * overflow, select and multi-select menus. Maximum length for the `text` in this field is 75 characters.
   */
  text: PlainTextElement;
}

/**
 * @description Defines a single item in a number of item selection elements. An object that represents a single
 * selectable item in a select menu, multi-select menu, checkbox group, radio button group, or overflow menu.
 * @see {@link https://docs.slack.dev/reference/block-kit/composition-objects/option-object Option object reference}.
 */
export type Option = MrkdwnOption | PlainTextOption;

/**
 * @description Defines a way to group options in a select or multi-select menu.
 * @see {@link https://docs.slack.dev/reference/block-kit/composition-objects/option-group-object Option group object reference}.
 */
export interface OptionGroup {
  /**
   * @description A {@link PlainTextElement} text object that defines the label shown above this group of options.
   * Maximum length for the `text` in this field is 75 characters.
   */
  label: PlainTextElement;
  /**
   * @description An array of {@link Option} that belong to this specific group. Maximum of 100 items.
   */
  options: Option[];
}

/**
 * @description Defines an object containing some text. Can be either a {@link PlainTextElement} or a
 * {@link MrkdwnElement}.
 * @see {@link https://docs.slack.dev/reference/block-kit/composition-objects/text-object Text object reference}.
 */
export type TextObject = PlainTextElement | MrkdwnElement;

/**
 * @description Defines an object containing some text.
 * @see {@link https://docs.slack.dev/reference/block-kit/composition-objects/text-object Text object reference}.
 */
export interface PlainTextElement {
  /**
   * @description The formatting to use for this text object.
   */
  type: 'plain_text';
  /**
   * @description The text for the block. The minimum length is 1 and maximum length is 3000 characters.
   */
  text: string;
  /**
   * @description Indicates whether emojis in a text field should be escaped into the colon emoji format.
   */
  emoji?: boolean;
}

/**
 * @description Defines an object containing some text.
 * @see {@link https://docs.slack.dev/reference/block-kit/composition-objects/text-object Text object reference}.
 */
export interface MrkdwnElement {
  /**
   * @description The formatting to use for this text object.
   */
  type: 'mrkdwn';
  /**
   * @description The text for the block. This field accepts any of the standard text formatting markup.
   * The minimum length is 1 and maximum length is 3000 characters.
   */
  text: string;
  /**
   * @description When set to `false` (as is default) URLs will be auto-converted into links, conversation names will
   * be link-ified, and certain mentions will be {@link https://docs.slack.dev/messaging/formatting-message-text automatically parsed}.
   * Using a value of `true` will skip any preprocessing of this nature, although you can still include
   * {@link https://docs.slack.dev/messaging/formatting-message-text manual parsing strings}.
   */
  verbatim?: boolean;
}

/**
 * @description Defines an object containing a numeric value.
 */
export interface RawNumberElement {
  /**
   * @description The formatting to use for this numeric object.
   */
  type: 'raw_number';
  /**
   * @description The numeric value.
   */
  value: number;
  /**
   * @description The text used to display the value. The minimum length is 1 character.
   */
  text: string;
}

/**
 * @description Defines an object containing some text.
 * @see {@link https://docs.slack.dev/reference/block-kit/composition-objects/text-object Text object reference}.
 */
export interface RawTextElement {
  /**
   * @description The formatting to use for this text object.
   */
  type: 'raw_text';
  /**
   * @description The text for the block. The minimum length is 1 character.
   */
  text: string;
}

interface BaseConversationFilter {
  /**
   * @description Indicates which type of conversations should be included in the list. When this field is provided, any
   * conversations that do not match will be excluded. You should provide an array of strings from the following options:
   * `im`, `mpim`, `private`, and `public`. The array cannot be empty.
   */
  include?: [ConversationType, ...ConversationType[]];
  /**
   * @description Indicates whether to exclude external {@link https://docs.slack.dev/apis/slack-connect shared channels}
   * from conversation lists. This field will not exclude users from shared channels. Defaults to `false`.
   */
  exclude_external_shared_channels?: boolean;
  /**
   * @description Indicates whether to exclude bot users from conversation lists. Defaults to `false`.
   */
  exclude_bot_users?: boolean;
}

/**
 * @description Defines a filter for the list of options in a conversation selector menu. The menu can be either a
 * conversations select menu or a conversations multi-select menu.
 * @see {@link https://docs.slack.dev/reference/block-kit/composition-objects/conversation-filter-object Conversation filter object reference}.
 */
export type ConversationFilter =
  | (BaseConversationFilter & Required<Pick<BaseConversationFilter, 'include'>>)
  | (BaseConversationFilter & Required<Pick<BaseConversationFilter, 'exclude_bot_users'>>)
  | (BaseConversationFilter & Required<Pick<BaseConversationFilter, 'exclude_external_shared_channels'>>);
/**
 * @description Object for image which contains a image_url.
 */
export interface UrlImageObject {
  /**
   * @description The URL of the image to be displayed.
   */
  image_url: string;
}

/**
 * @description Object for image which contains a slack_file.
 */
export interface SlackFileImageObject {
  /**
   * @description The slack file of the image to be displayed.
   */
  slack_file: SlackFile;
}

interface SlackFileViaUrl {
  /**
   * @description This URL can be the `url_private` or the `permalink` of the {@link Slack file https://docs.slack.dev/reference/objects/file-object}.
   */
  url: string;
}

interface SlackFileViaId {
  /**
   * @description `id` of the {@link Slack file https://docs.slack.dev/reference/objects/file-objecte}.
   */
  id: string;
}

/**
 * @description Defines an object containing Slack file information to be used in an image block or image element.
 * This {@link file https://docs.slack.dev/reference/objects/file-object} must be an image and you must provide either the URL or ID. In addition,
 * the user posting these blocks must have access to this file. If both are provided then the payload will be rejected.
 * Currently only `png`, `jpg`, `jpeg`, and `gif` Slack image files are supported.
 * @see {@link https://docs.slack.dev/reference/block-kit/composition-objects/slack-file-object Slack File object reference}.
 */
export type SlackFile = SlackFileViaUrl | SlackFileViaId;

// This file contains reusable extensions/mixins that other Block Kit elements will extend from.
import type { ConfirmationDialog, DispatchActionConfig, PlainTextElement } from './composition-objects';

// TODO: breaking change: remove `Action` and move properties to `Actionable` on next major release.
/**
 * @deprecated {@link Action} aliased to {@link Actionable} in order to name the mixins in this file consistently.
 */
export interface Action {
  type: string;
  /**
   * @description: An identifier for this action. You can use this when you receive an interaction payload to
   * {@link https://docs.slack.dev/interactivity/handling-user-interaction#payloads identify the source of the action}. Should be unique
   * among all other `action_id`s in the containing block. Maximum length for this field is 255 characters.
   */
  action_id?: string;
}

export interface Actionable extends Action {}

export interface Confirmable {
  /**
   * @description A {@link Confirm} object that defines an optional confirmation dialog after the element is interacted
   * with.
   */
  confirm?: ConfirmationDialog;
}

export interface Dispatchable {
  /**
   * @description A {@link DispatchActionConfig} object that determines when during text input the element returns a
   * {@link https://docs.slack.dev/reference/interaction-payloads/block_actions-payload `block_actions` payload}.
   */
  dispatch_action_config?: DispatchActionConfig;
}

export interface Focusable {
  /**
   * @description Indicates whether the element will be set to auto focus within the
   * {@link https://docs.slack.dev/surfaces/modals `view` object}. Only one element can be set to `true`.
   * Defaults to `false`.
   */
  focus_on_load?: boolean;
}

export interface MaxItemsSelectable {
  /**
   * @description Specifies the maximum number of items that can be selected. Minimum number is 1.
   */
  max_selected_items?: number;
}

export interface Placeholdable {
  /**
   * @description A {@link PlainTextElement} object that defines the placeholder text shown on the element. Maximum
   * length for the `text` field in this object is 150 characters.
   */
  placeholder?: PlainTextElement;
}

export interface URLRespondable {
  /**
   * @description When set to `true`, the {@link https://docs.slack.dev/reference/interaction-payloads/view-interactions-payload#view_submission `view_submission` payload}
   * from the menu's parent view will contain a `response_url`. This `response_url` can be used for
   * {@link https://docs.slack.dev/interactivity/handling-user-interaction#message_responses message responses}. The target conversation
   * for the message will be determined by the value of this select menu.
   */
  response_url_enabled?: boolean;
}

/** For use in setting border style details on certain Rich Text elements. */
export interface RichTextBorderable {
  /**
   * @description Whether to render a quote-block-like border on the inline side of the list. `0` renders no border
   * while `1` renders a border.
   */
  border?: 0 | 1;
}

/**
 * @description For use styling Rich Text sub-elements.
 */
export interface RichTextStyleable {
  /**
   * @description A limited style object for styling rich text `text` elements.
   */
  style?: {
    /** @description When `true`, boldens the text in this element. Defaults to `false`. */
    bold?: boolean;
    /** @description When `true`, the text is preformatted in an inline code style. Defaults to `false. */
    code?: boolean;
    /** @description When `true`, italicizes the text in this element. Defaults to `false`. */
    italic?: boolean;
    /** @description When `true`, strikes through the text in this element. Defaults to `false`. */
    strike?: boolean;
    /** @description When `true`, underlines the text in this element. Defaults to `false`. */
    underline?: boolean;
  };
}

// These types represent users in Slack Calls, which is an API for showing 3rd party calls within the Slack client.
// More information on the API guide for Calls: https://docs.slack.dev/apis/web-api/using-the-calls-api
// and on User objects for use with Calls: https://docs.slack.dev/apis/web-api/using-the-calls-api

/**
 * @description For use in representing {@link https://docs.slack.dev/apis/web-api/using-the-calls-api users in a Slack Call}.
 */
export type CallUser = CallUserSlack | CallUserExternal;

export interface CallUserSlack {
  /**
   * @description The Slack encoded user ID, e.g. U1234ABCD. Set this if you have it or know it, otherwise, set
   * `external_id` and `display_name`.
   */
  slack_id: string;
}

export interface CallUserExternal {
  /**
   * @description A unique ID created by your app to represent your users.
   */
  external_id: string;
  /**
   * @description Name of the user to be displayed in the Call block in a message.
   */
  display_name: string;
  /**
   * @description URL to an avatar image of the user.
   */
  avatar_url?: string;
}

import type { URLSourceElement } from './block-kit/block-elements';
import type { AnyBlock } from './block-kit/blocks';

/**
 * Base interface for streaming message chunks.
 * https://docs.slack.dev/messaging/sending-and-scheduling-messages#text-streaming
 */
export interface Chunk {
  type: string;
}

/**
 * Used for passing an array of blocks within a streaming message.
 * https://docs.slack.dev/changelog/2026/04/16/block-kit-new-blocks/
 */
export interface BlocksChunk extends Chunk {
  type: 'blocks';
  /** @description An array of {@link AnyBlock} objects. Maximum of 50 blocks. */
  blocks: AnyBlock[];
}

/**
 * Used for streaming text content with markdown formatting support.
 * https://docs.slack.dev/messaging/sending-and-scheduling-messages#text-streaming
 */
export interface MarkdownTextChunk extends Chunk {
  type: 'markdown_text';
  text: string;
}

/**
 * Used for displaying an updated title of a plan.
 * https://docs.slack.dev/messaging/sending-and-scheduling-messages#text-streaming
 */
export interface PlanUpdateChunk extends Chunk {
  type: 'plan_update';
  title: string;
}

/**
 * Used for displaying task progress in a timeline-style UI.
 * https://docs.slack.dev/messaging/sending-and-scheduling-messages#text-streaming
 */
export interface TaskUpdateChunk extends Chunk {
  type: 'task_update';
  id: string;
  title: string;
  status: 'pending' | 'in_progress' | 'complete' | 'error';
  details?: string;
  output?: string;
  sources?: URLSourceElement[];
}

/**
 * Union type of all possible chunk types
 */
export type AnyChunk = BlocksChunk | MarkdownTextChunk | PlanUpdateChunk | TaskUpdateChunk;

