export type MessageEvent = AllMessageEvents;

export interface GenericMessageEvent {
  type: 'message';
  subtype: undefined;
  event_ts: string;
  team?: string;
  channel: string;
  user: string;
  bot_id?: string;
  bot_profile?: BotProfile;
  text?: string;
  ts: string;
  thread_ts?: string;
  channel_type: ChannelTypes;
  attachments?: MessageAttachment[];
  blocks?: (KnownBlock | Block)[];
  files?: File[];
  edited?: {
    user: string;
    ts: string;
  };
  client_msg_id?: string;
  parent_user_id?: string;

  // TODO: optional types that maybe should flow into other subtypes?
  is_starred?: boolean;
  pinned_to?: string[];
  reactions?: {
    name: string;
    count: number;
    users: string[];
  }[];

  // TODO: add properties to this field once it's publicly released
  assistant_thread?: Record<string, unknown>;

  app_context?: AppContextChangedEvent['context'];
}

export interface BotMessageEvent {
  type: 'message';
  subtype: 'bot_message';
  event_ts: string;
  channel: string;
  channel_type: ChannelTypes;
  streaming_state?: 'in_progress' | 'completed' | 'errored';
  ts: string;
  text: string;
  bot_id: string;
  username?: string;
  icons?: {
    [size: string]: string;
  };

  // copied from MessageEvent
  // TODO: is a user really optional? likely for things like IncomingWebhook authored messages
  user?: string;
  attachments?: MessageAttachment[];
  blocks?: (KnownBlock | Block)[];
  edited?: {
    user: string;
    ts: string;
  };
  thread_ts?: string;
}

